-- Canonical launch surfaces for Community, provider network, and participant preferences.
create table if not exists public.community_posts (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, author_user_id uuid not null references auth.users(id) on delete cascade, kind text not null check (kind in ('discussion','update','event')), title text not null check (char_length(btrim(title)) between 1 and 160), body text not null check (char_length(btrim(body)) between 1 and 5000), event_at timestamptz, status text not null default 'active' check (status in ('active','hidden')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.community_reviews (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, job_id uuid not null references public.crm_jobs(id) on delete cascade, author_user_id uuid not null references auth.users(id) on delete cascade, rating int not null check (rating between 1 and 5), body text not null check (char_length(btrim(body)) between 1 and 3000), status text not null default 'published' check (status in ('published','reported','hidden')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(job_id,author_user_id));
create table if not exists public.community_referrals (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, referrer_user_id uuid not null references auth.users(id) on delete cascade, referred_email text not null, note text, status text not null default 'recorded' check (status in ('recorded','accepted','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.community_reports (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, reporter_user_id uuid not null references auth.users(id) on delete cascade, post_id uuid references public.community_posts(id) on delete cascade, review_id uuid references public.community_reviews(id) on delete cascade, reason text not null check (char_length(btrim(reason)) between 1 and 1000), status text not null default 'open' check (status in ('open','resolved','dismissed')), created_at timestamptz not null default now(), resolved_at timestamptz, resolved_by uuid references auth.users(id), check ((post_id is not null)::int + (review_id is not null)::int = 1));
create table if not exists public.provider_service_areas (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, contractor_id bigint not null references public.contractors(id) on delete cascade, city text, state text, zip text, radius_miles int check (radius_miles is null or radius_miles between 1 and 250), created_at timestamptz not null default now(), unique(contractor_id,city,state,zip));
create table if not exists public.provider_availability (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, contractor_id bigint not null references public.contractors(id) on delete cascade, available boolean not null default true, note text, next_available_at timestamptz, updated_at timestamptz not null default now(), unique(contractor_id));
create table if not exists public.saved_providers (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, contractor_id bigint not null references public.contractors(id) on delete cascade, created_at timestamptz not null default now(), unique(user_id,contractor_id));
create table if not exists public.participant_preferences (user_id uuid primary key references auth.users(id) on delete cascade, workspace_id uuid not null references public.workspaces(id) on delete cascade, phone text, preferred_contact text check (preferred_contact is null or preferred_contact in ('email','phone','sms')), accessibility_notes text, language text not null default 'en', network_visibility text not null default 'workspace' check (network_visibility in ('private','workspace','network')), updated_at timestamptz not null default now());
alter table public.community_posts enable row level security; alter table public.community_reviews enable row level security; alter table public.community_referrals enable row level security; alter table public.community_reports enable row level security; alter table public.provider_service_areas enable row level security; alter table public.provider_availability enable row level security; alter table public.saved_providers enable row level security; alter table public.participant_preferences enable row level security;
create or replace function public.hlc_is_workspace_member(p_workspace_id uuid) returns boolean language sql stable security invoker set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=auth.uid()) $$;
create or replace function public.hlc_is_workspace_owner(p_workspace_id uuid) returns boolean language sql stable security invoker set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.profiles p where p.workspace_id=p_workspace_id and p.user_id=auth.uid() and lower(p.role)='owner') $$;
create policy community_posts_select on public.community_posts for select to authenticated using (public.hlc_is_workspace_member(workspace_id));
create policy community_posts_insert on public.community_posts for insert to authenticated with check (public.hlc_is_workspace_member(workspace_id) and author_user_id=auth.uid());
create policy community_posts_update on public.community_posts for update to authenticated using (author_user_id=auth.uid() or public.hlc_is_workspace_owner(workspace_id)) with check (public.hlc_is_workspace_member(workspace_id));
create policy community_reviews_select on public.community_reviews for select to authenticated using (public.hlc_is_workspace_member(workspace_id));
create policy community_reviews_insert on public.community_reviews for insert to authenticated with check (public.hlc_is_workspace_member(workspace_id) and author_user_id=auth.uid() and exists(select 1 from public.crm_jobs j where j.id=job_id and j.workspace_id=workspace_id and j.status='completed'));
create policy community_referrals_select on public.community_referrals for select to authenticated using (referrer_user_id=auth.uid() or public.hlc_is_workspace_owner(workspace_id));
create policy community_referrals_insert on public.community_referrals for insert to authenticated with check (public.hlc_is_workspace_member(workspace_id) and referrer_user_id=auth.uid());
create policy community_reports_select on public.community_reports for select to authenticated using (reporter_user_id=auth.uid() or public.hlc_is_workspace_owner(workspace_id));
create policy community_reports_insert on public.community_reports for insert to authenticated with check (public.hlc_is_workspace_member(workspace_id) and reporter_user_id=auth.uid());
create policy community_reports_update on public.community_reports for update to authenticated using (public.hlc_is_workspace_owner(workspace_id)) with check (public.hlc_is_workspace_owner(workspace_id));
create policy provider_service_areas_all on public.provider_service_areas for all to authenticated using (public.hlc_is_workspace_member(workspace_id)) with check (public.hlc_is_workspace_member(workspace_id));
create policy provider_availability_all on public.provider_availability for all to authenticated using (public.hlc_is_workspace_member(workspace_id)) with check (public.hlc_is_workspace_member(workspace_id));
create policy saved_providers_all on public.saved_providers for all to authenticated using (user_id=auth.uid() and public.hlc_is_workspace_member(workspace_id)) with check (user_id=auth.uid() and public.hlc_is_workspace_member(workspace_id));
create policy participant_preferences_all on public.participant_preferences for all to authenticated using (user_id=auth.uid() and public.hlc_is_workspace_member(workspace_id)) with check (user_id=auth.uid() and public.hlc_is_workspace_member(workspace_id));
create index if not exists community_posts_workspace_created_idx on public.community_posts(workspace_id,created_at desc); create index if not exists community_reviews_workspace_created_idx on public.community_reviews(workspace_id,created_at desc); create index if not exists community_reports_workspace_status_idx on public.community_reports(workspace_id,status,created_at desc); create index if not exists provider_service_areas_workspace_idx on public.provider_service_areas(workspace_id,contractor_id);
